import{_ as l,l as s,o as e,c as n,v as t,p as i,x as o,d as C,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"分组模式 CBC / GCM","description":"","frontmatter":{"title":"分组模式 CBC / GCM","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/block-modes.md","filePath":"cs/block-modes.md","lastUpdated":1789023840000}'),A={name:"cs/block-modes.md"};function B(p,a,E,h,_,m){const r=s("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="分组模式-cbc-gcm" tabindex="-1">分组模式 CBC / GCM <a class="header-anchor" href="#分组模式-cbc-gcm" aria-label="Permalink to &quot;分组模式 CBC / GCM&quot;">​</a></h1><div class="epigraph"><p>分组密码只加密定长块；CBC 用链式 IV 扩到消息，GCM 再把保密与完整性收成一次 AEAD。</p><footer>—— 据 NIST 对 CBC 与 GCM；Stallings；Anderson 对「只加密不够」的整理</footer></div><p><a href="/cs/symmetric-crypto">上一课</a>给出共享密钥下的语义安全直觉。本课不重定义「不可区分」。缺口是工作模式：ECB 泄露相等块；CBC 需要不可预测 IV；仅加密不防篡改。<a href="/cs/dolev-yao">Dolev–Yao</a> 的理想锁在真实模式选错时并不成立。公钥信封下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>对称课留下「工作模式」。消息长度不是一块。CBC：IV 异或后链式，解密可并行。缺完整性时，密文被改可能变成对明文的可控差异——本课只陈述性质与防御：必须另加 MAC 或改用 AEAD。GCM：CTR 保密 + GHASH 认证，IV 不得复用。缺口是<strong>模式如何兑现 C 与 I</strong>。</p><p><span class="marginnote">IV/nonce 复用是规格失败，不是「算法过时」。防御是随机 IV、唯一 nonce、或协议层禁止重用。不给构造步骤。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>只保密：CBC + 独立 MAC（Encrypt-then-MAC）是经典组合。优先 AEAD（GCM 等）：一次密钥、一次 nonce、密文带认证标签。TLS 1.3 只保留 AEAD 套件（后课 RFC 8446）。本课不比较全部厂商模式缩写。</p>',8)),(e(),i(d,null,{default:o(()=>[c(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20BLK%5B%22%E5%88%86%E7%BB%84%E5%AF%86%E7%A0%81%22%5D%20--%3E%20CBC%5B%22CBC%20%E9%93%BE%E5%BC%8F%20%2B%20IV%22%5D%0A%20%20BLK%20--%3E%20GCM%5B%22GCM%3A%20CTR%20%E5%8A%A0%20GHASH%22%5D%0A%20%20CBC%20--%3E%20MAC%5B%22%E4%BB%8D%E9%9C%80%E7%8B%AC%E7%AB%8B%E5%AE%8C%E6%95%B4%E6%80%A7%22%5D%0A%20%20GCM%20--%3E%20AEAD%5B%22%E4%B8%80%E6%AC%A1%E7%BB%99%E5%87%BA%20C%20%E4%B8%8E%20I%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[C(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>模式把块函数变成消息函数。完整性失败会让 DY 敌手「改项仍被当成合法密文」，理想锁破产。IV 是状态，不是密钥，但必须按模式合同使用。后课公钥只运这把对称键，大数据仍走本课 AEAD。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入填充预言的操作细节，不把任何利用链写成可复现步骤。第一次见面如何分发密钥，下一课公钥与信封。</p><p>后课默认：长消息用 AEAD。密钥分发用公钥封装。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CBC 扩块；单独加密不给完整性。</li><li>GCM 一类 AEAD 同时服务 C 与 I。</li><li>公钥信封下一课。</li><li>出处：NIST 模式；Stallings；Anderson。</li></ul>',7))])}const D=l(A,[["render",B]]);export{f as __pageData,D as default};
